const now = new Date();
const day = now.getUTCDay();
const hour = now.getUTCHours();

if (day === 5 && hour >= 18) return [];
if (day === 6) return [];
if (day === 0 && hour < 21) return [];

return items;

// Strategy 1: Momentum EMA Scalper
const candles = items[0].json.candles;
if (!candles || candles.length < 21) throw new Error("Not enough data");

const closes = candles.map(c => parseFloat(c.mid.c));
const ema = (data, period) => {
  const k = 2 / (period + 1);
  return data.reduce((acc, price, i) => {
    if (i === 0) return [price];
    acc.push((price - acc[i - 1]) * k + acc[i - 1]);
    return acc;
  }, []);
};

const ema9 = ema(closes, 9).slice(-1)[0];
const ema20 = ema(closes, 20).slice(-1)[0];
const last = candles[candles.length - 1];
const lastClose = parseFloat(last.mid.c);
const lastLow = parseFloat(last.mid.l);
const lastHigh = parseFloat(last.mid.h);
const touchedEma9 = lastLow <= ema9 && lastHigh >= ema9;

let signal = 'none';
if (ema9 > ema20 && touchedEma9 && lastClose > ema9) signal = 'BUY';
if (ema9 < ema20 && touchedEma9 && lastClose < ema9) signal = 'SELL';

return [{
  json: {
    strategy: 'Momentum EMA Scalper',
    timeframe: $node["Set Inputs"].json["timeframe"],
    signal,
    lastClose,
    ema9,
    ema20,
    time: last.time,
