  }
}];

/**
 * Function node: “Compute RSI Signal (All-In-One)”
 * Preceded by:
 *   • “Set Inputs2” node providing:
 *       - instrument       (e.g. "EUR_USD")
 *       - timeframe        (e.g. "M5")
 *       - riskPct          (percent of account, e.g. 1 for 1%)
 *       - accountBalance   (e.g. 500 or 1000)
 *       - oanda_account_id
 *       - telegram_id
 *       - telegram_topic_id
 *   • An HTTP Request node fetching ≥60 M5 candles into items[0].json.candles
 */

// ── 1) STRATEGY PARAMETERS (BAKED IN) ───────────────────────────────────────────
const rsiPeriod    = 14;      // look‐back for RSI
const oversold     = 30;      // RSI threshold for oversold
const overbought   = 70;      // RSI threshold for overbought
const smaPeriod    = 50;      // look‐back for trend filter
const atrPeriod    = 14;      // look‐back for volatility stops
const rrRatio      = 1.5;     // take‐profit = stop‐loss × rrRatio

// ── 2) INPUT VALIDATION ────────────────────────────────────────────────────────
const inputs  = $node["Set Inputs2"].json;
const candles = items[0].json.candles;
const minCandles = Math.max(rsiPeriod + 1, smaPeriod, atrPeriod + 1);

if (!Array.isArray(candles) || candles.length < minCandles) {
  throw new Error(`Need at least ${minCandles} candles, got ${candles?.length || 0}`);
}

// ── 3) EXTRACT PRICE ARRAYS ────────────────────────────────────────────────────
const closes = candles.map(c => parseFloat(c.mid.c) || 0);
const highs  = candles.map(c => parseFloat(c.mid.h) || 0);
const lows   = candles.map(c => parseFloat(c.mid.l) || 0);

// ── 4) WILDER’S RSI SERIES ─────────────────────────────────────────────────────
function calcRSI(prices, length) {
  let gain = 0, loss = 0;
  for (let i = 1; i <= length; i++) {
    const d = prices[i] - prices[i - 1];
    if (d > 0) gain += d;
    else loss += -d;
  }
  let avgG = gain / length;
  let avgL = loss / length;
  const out = [100 - (100 / (1 + avgG / (avgL || 1)))];
  for (let i = length + 1; i < prices.length; i++) {
    const d = prices[i] - prices[i - 1];
    const g = d > 0 ? d : 0;
    const l = d < 0 ? -d : 0;
    avgG = (avgG * (length - 1) + g) / length;
    avgL = (avgL * (length - 1) + l) / length;
    out.push(100 - (100 / (1 + avgG / (avgL || 1))));
  }
  return out;
}

const rsiArr     = calcRSI(closes, rsiPeriod);
const prevRSI    = rsiArr[rsiArr.length - 2];
const currentRSI = rsiArr[rsiArr.length - 1];

// ── 5) SMA TREND FILTER ────────────────────────────────────────────────────────
const sma = closes
  .slice(-smaPeriod)
  .reduce((sum, v) => sum + v, 0) / smaPeriod;

// ── 6) ATR-BASED STOP-LOSS & TAKE-PROFIT ───────────────────────────────────────
function calcATR(highs, lows, closes, length) {
  const trs = [];
  for (let i = 1; i < highs.length; i++) {
    trs.push(Math.max(
      highs[i] - lows[i],
      Math.abs(highs[i] - closes[i - 1]),
      Math.abs(lows[i]  - closes[i - 1])
    ));
  }
  let atr = trs.slice(0, length).reduce((s, v) => s + v, 0) / length;
  for (let i = length; i < trs.length; i++) {
    atr = (atr * (length - 1) + trs[i]) / length;
  }
  return atr;
}

const atr     = calcATR(highs, lows, closes, atrPeriod);
const pipSize = inputs.instrument.endsWith("_JPY") ? 0.01 : 0.0001;
const slPips  = Math.max(1, Math.round(atr / pipSize));
const tpPips  = Math.round(slPips * rrRatio);

// ── 7) POSITION SIZING ─────────────────────────────────────────────────────────
const accountBalance = parseFloat(inputs.accountBalance);
const riskAmount     = (parseFloat(inputs.riskPct) / 100) * accountBalance;
const units          = Math.floor(riskAmount / (slPips * pipSize));

// ── 8) SIGNAL LOGIC (CROSSINGS + TREND) ───────────────────────────────────────
let rawSignal = "none";
if (prevRSI < oversold && currentRSI > oversold)   rawSignal = "BUY";
else if (prevRSI > overbought && currentRSI < overbought) rawSignal = "SELL";

const lastPrice = closes[closes.length - 1];
const signal = (rawSignal === "BUY"  && lastPrice > sma) ? "BUY"
              : (rawSignal === "SELL" && lastPrice < sma) ? "SELL"
              : "none";

// ── 9) STRUCTURED LOGGING ───────────────────────────────────────────────────────
console.log(JSON.stringify({
  timestamp:   new Date().toISOString(),
  strategy:    "RSI+SMA+ATR",
  instrument:  inputs.instrument,
  timeframe:   inputs.timeframe,
  prevRSI,
  currentRSI,
  sma,
  atr,
  slPips,
  tpPips,
  units,
  signal
}));

// ── 10) OUTPUT ─────────────────────────────────────────────────────────────────
return [{
  json: {
    strategy:       "RSI+SMA+ATR",
    instrument:     inputs.instrument,
    timeframe:      inputs.timeframe,
    signal,
    lastPrice,
    prevRSI,
    currentRSI,
    sma,
    atr,
    stopLossPips:   slPips,
    takeProfitPips: tpPips,
    units,
    accountId:      inputs.oanda_account_id,
    telegram_id:    inputs.telegram_id,
    telegram_topic_id: inputs.telegram_topic_id,
  }
}];

