const item = $input.item.json;

const signal = item.signal;
const account = item.account;

if (!signal || !account || !account.balance) {
  throw new Error("Missing signal or account data.");
}

const accountBalance = parseFloat(account.balance);
const riskPercentage = parseFloat(signal.riskPercentage) / 100;
const stopLossPips = signal.stopLossPips;
const pipValue = 0.0001;
const signalType = signal.signal;
const entryPrice = signal.lastClose;
const rr = parseFloat(signal.riskRewardRatio || 1.5); // Default RR if missing

const riskAmount = accountBalance * riskPercentage;
const positionSize = Math.round(riskAmount / (stopLossPips * pipValue));
const isBuy = signalType === 'BUY';

const stopLossPrice = (isBuy
  ? entryPrice - (stopLossPips * pipValue)
  : entryPrice + (stopLossPips * pipValue)).toFixed(5);

const takeProfitPrice = (isBuy
  ? entryPrice + (stopLossPips * pipValue * rr)
  : entryPrice - (stopLossPips * pipValue * rr)).toFixed(5);

const units = isBuy ? positionSize : -positionSize;

return {
  json: {
    ...signal,
    accountId: account.id,
    accountBalance,
    riskAmount,
    positionSize: units,
    stopLossPrice,
    takeProfitPrice
  }
};

const validSignals = items
  .filter(i => {
    const signal = i.json.signal;
    return signal && signal !== 'none';
  })
  .map(i => {
    return {
      json: {
        signal: i.json
      }
    };
  });


return validSignals.json ? validSignals: {
      json: {
        signal: true
      }
    }
